import json

import httpx


class ErreurApi(Exception):
    """Base des erreurs de la couche API."""


class ApiIndisponible(ErreurApi):
    """Réseau, timeout, 5xx : réessayer plus tard a du sens."""


class RequeteInvalide(ErreurApi):
    """4xx : la requête est fausse, réessayer ne changera rien."""


class DonneesInattendues(ErreurApi):
    """200 mais contenu hors contrat : l'API a changé ?"""


def appeler(client: httpx.Client, url: str, cle_reponse: str) -> dict:
    try:
        reponse = client.get(url)
        reponse.raise_for_status()
    except httpx.TimeoutException as exc:
        raise ApiIndisponible(f"timeout sur {url}") from exc
    except httpx.TransportError as exc:                  # ConnectError inclus
        raise ApiIndisponible(f"réseau inaccessible : {url}") from exc
    except httpx.HTTPStatusError as exc:
        code = exc.response.status_code
        if code >= 500:
            raise ApiIndisponible(f"{url} → {code}") from exc
        raise RequeteInvalide(f"{url} → {code}") from exc

    try:
        corps = reponse.json()
        return corps[cle_reponse]
    except json.JSONDecodeError as exc:
        raise DonneesInattendues(f"{url} : corps non-JSON") from exc
    except KeyError as exc:
        raise DonneesInattendues(f"{url} : clé {cle_reponse!r} absente "
                                 f"(reçu : {list(corps)})") from exc


# --- les quatre chemins ---
with httpx.Client(timeout=2.0) as client:
    print(appeler(client, "http://127.0.0.1:8200/donnees", "valeur"))    # 42

    for url, attendu in [
        ("http://127.0.0.1:8200/inexistant", RequeteInvalide),
        ("http://127.0.0.1:8999/donnees", ApiIndisponible),      # port fermé
    ]:
        try:
            appeler(client, url, "valeur")
        except ErreurApi as exc:
            assert isinstance(exc, attendu), exc
            print(f"{attendu.__name__} ✓ — {exc}")

    try:
        appeler(client, "http://127.0.0.1:8200/donnees", "cle_qui_nexiste_pas")
    except DonneesInattendues as exc:
        print(f"DonneesInattendues ✓ — {exc}")
```

Réponse à la question 4 — ce que gagne la couche appelante :

- **Un vocabulaire de DÉCISIONS, pas de causes** : `ApiIndisponible` → afficher « réessaie plus tard » / planifier un retry ; `RequeteInvalide` → bug à corriger, alerter le développeur ; `DonneesInattendues` → l'API a changé, geler la fonctionnalité. Le CLI n'a pas à connaître la différence entre un ConnectError et un ReadTimeout — elle ne change pas sa réaction.
- **Découplage** : remplacer httpx par autre chose (ou ajouter un cache) ne touche que ce module.
- **Pour l'agent IA du chapitre 18** : ces trois exceptions deviendront des messages d'erreur structurés que le LLM peut comprendre et sur lesquels il peut raisonner (« la source est indisponible, j'utilise le cache »). Une traceback httpx brute ne le permettrait pas.

Le message de `DonneesInattendues` liste les clés reçues : quand une API change de format en production, ce détail vaut une heure de debug.
